38	async function getJSON<T>(url: string): Promise<T> {
39	  const res = await fetch(url)
40	  if (!res.ok) {
41	    let message = `${res.status} ${res.statusText}`
42	    try {
43	      const body = (await res.json()) as { error?: string }
44	      if (body?.error) message = body.error
45	    } catch {
46	      // response had no JSON error body; keep the status line
47	    }
48	    throw new Error(message)
49	  }
50	  return (await res.json()) as T
51	}
52	
53	export const api = {
54	  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
55	  getIntegration: (path: string) =>
56	    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
