import { Fragment } from 'react'
import type { IntegrationDetail } from '../api'
import {
  ChevronRightIcon,
  ExtensionIcon,
  MemoryIcon,
  RouteIcon,
} from '../icons'

interface Props {
  detail: IntegrationDetail | null
  hasSelection: boolean
}

export function FlowView({ detail, hasSelection }: Props) {
  if (!hasSelection) {
    return <p className="empty">Select an integration to see its flow.</p>
  }
  if (!detail) {
    return <p className="empty">Loading…</p>
  }

  const steps = detail.pipelineSteps ?? []
  const components = detail.daprComponents ?? []

  return (
    <article className="detail">
      <h1 className="detail-title">{title(detail)}</h1>

      {steps.length === 0 ? (
        <p className="muted">This integration has no pipeline steps to visualise.</p>
      ) : (
        <div className="flow">
          <FlowNode kind="trigger" label="Trigger" sub={detail.template || 'entry'} />
          {steps.map((s) => (
            <Fragment key={s}>
              <ChevronRightIcon className="flow-arrow" aria-hidden />
              <FlowNode kind="step" label={stepName(s)} sub={s} />
            </Fragment>
          ))}
          <ChevronRightIcon className="flow-arrow" aria-hidden />
          <FlowNode kind="sink" label="Output" sub="loader" />
        </div>
      )}

      {components.length > 0 && (
        <section className="section">
          <h2 className="section-title">
            <ExtensionIcon className="icon" aria-hidden />
            Dapr components
          </h2>
          <ul className="chips">
            {components.map((c) => (
              <li key={c} className="chip">
                {c}
              </li>
            ))}
          </ul>
        </section>
      )}
    </article>
  )
}

function FlowNode({
  kind,
  label,
  sub,
}: {
  kind: 'trigger' | 'step' | 'sink'
  label: string
  sub: string
}) {
  const Icon = kind === 'step' ? RouteIcon : MemoryIcon
  return (
    <div className={`flow-node ${kind}`}>
      <Icon className="flow-node-icon" aria-hidden />
      <span className="flow-node-label">{label}</span>
      <span className="flow-node-sub">{sub}</span>
    </div>
  )
}

// title matches the catalog view: domain / system / name.
function title(detail: IntegrationDetail): string {
  const name = detail.name || detail.path
  return [detail.domain, detail.system, name].filter(Boolean).join(' / ')
}

// stepName turns a source filename like "OrderValidateStep.cs" into a readable
// "Order Validate".
function stepName(file: string): string {
  return file
    .replace(/\.[^.]+$/, '')
    .replace(/Step$/, '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
}

