import { useEffect, useMemo, useState } from 'react'
import {
  Background,
  Controls,
  MiniMap,
  ReactFlow,
  useNodesState,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { api, type IntegrationDetail } from '../api'
import { ExtensionIcon, MemoryIcon, RouteIcon } from '../icons'

interface Props {
  selected: string | null
  onSelect: (path: string) => void
}

// Card + layout geometry. The layout is deterministic: systems stack top to
// bottom, their integrations flow left to right in a fixed-width grid.
const NODE_W = 300
const NODE_H = 172
const COL_GAP = 28
const ROW_GAP = 28
const COLS = 2
const GROUP_HEADER = 44
const GROUP_PAD = 20
const GROUP_GAP = 40

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  steps: string[]
  components: string[]
  selected: boolean
}

interface GroupNodeData extends Record<string, unknown> {
  title: string
  count: number
}

export function FlowView({ selected, onSelect }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])

  useEffect(() => {
    api
      .flow()
      .then(setGraph)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
  }, [])

  // Build the node graph whenever the data loads; positions are stable so a
  // reload lands things in the same place.
  const built = useMemo(() => (graph ? buildNodes(graph) : []), [graph])
  useEffect(() => setNodes(built), [built, setNodes])

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph) {
    return <p className="empty">Loading…</p>
  }
  if (graph.length === 0) {
    return <p className="empty">No integrations to visualise.</p>
  }

  return (
    <div className="flow-canvas">
      <ReactFlow
        nodes={nodes}
        edges={[]}
        onNodesChange={onNodesChange}
        nodeTypes={NODE_TYPES}
        colorMode="system"
        fitView
        fitViewOptions={{ padding: 0.2 }}
        minZoom={0.3}
        proOptions={{ hideAttribution: true }}
        onNodeClick={(_, node) => {
          if (node.type === 'integration') onSelect(node.id)
        }}
      >
        <Background gap={20} />
        <Controls showInteractive={false} />
        <MiniMap pannable zoomable />
      </ReactFlow>
    </div>
  )
}

// buildNodes groups integrations by their domain/system container and lays
// each group's integrations out in a grid.
function buildNodes(graph: IntegrationDetail[]): Node[] {
  const groups = new Map<string, { title: string; items: IntegrationDetail[] }>()
  for (const it of graph) {
    const key = [it.domain, it.system].filter(Boolean).join('/') || '(root)'
    const title = [it.domain, it.system].filter(Boolean).join(' / ') || 'Workspace'
    const g = groups.get(key) ?? { title, items: [] }
    g.items.push(it)
    groups.set(key, g)
  }

  const groupNodes: Node[] = []
  const childNodes: Node[] = []
  let y = 0

  for (const [key, group] of groups) {
    const n = group.items.length
    const cols = Math.min(COLS, n)
    const rows = Math.ceil(n / cols)
    const width = GROUP_PAD * 2 + cols * NODE_W + (cols - 1) * COL_GAP
    const height =
      GROUP_HEADER + GROUP_PAD + rows * NODE_H + (rows - 1) * ROW_GAP + GROUP_PAD

    groupNodes.push({
      id: `grp:${key}`,
      type: 'group',
      position: { x: 0, y },
      data: { title: group.title, count: n } satisfies GroupNodeData,
      style: { width, height },
      draggable: false,
      selectable: false,
    })

    group.items.forEach((it, i) => {
      const col = i % cols
      const row = Math.floor(i / cols)
      childNodes.push({
        id: it.path,
        type: 'integration',
        parentId: `grp:${key}`,
        extent: 'parent',
        position: {
          x: GROUP_PAD + col * (NODE_W + COL_GAP),
          y: GROUP_HEADER + row * (NODE_H + ROW_GAP),
        },
        data: {
          name: it.name,
          template: it.template,
          steps: it.pipelineSteps ?? [],
          components: it.daprComponents ?? [],
          selected: false,
        } satisfies IntNodeData,
      })
    })

    y += height + GROUP_GAP
  }

  // Parents must precede their children in the array.
  return [...groupNodes, ...childNodes]
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, steps, components, selected } = data as IntNodeData
  return (
    <div className={`rf-int${selected ? ' selected' : ''}`}>
      <div className="rf-int-head">
        <MemoryIcon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
      </div>

      <div className="rf-int-row">
        <RouteIcon className="rf-int-row-icon" aria-hidden />
        {steps.length === 0 ? (
          <span className="rf-int-empty">no steps</span>
        ) : (
          <div className="rf-int-chips">
            {steps.map((s) => (
              <span key={s} className="rf-chip">
                {stepName(s)}
              </span>
            ))}
          </div>
        )}
      </div>

      {components.length > 0 && (
        <div className="rf-int-row">
          <ExtensionIcon className="rf-int-row-icon" aria-hidden />
          <div className="rf-int-chips">
            {components.map((c) => (
              <span key={c} className="rf-chip infra">
                {componentName(c)}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

const NODE_TYPES = { group: GroupNode, integration: IntegrationNode }

// stepName turns "OrderValidateStep.cs" into "Order Validate".
function stepName(file: string): string {
  return file
    .replace(/\.[^.]+$/, '')
    .replace(/Step$/, '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
}

// componentName drops the yaml extension from a Dapr component filename.
function componentName(file: string): string {
  return file.replace(/\.ya?ml$/, '')
}

